    solar_system = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in solar_system or planet2 not in solar_system:
        return ()

    start_index = solar_system.index(planet1)
    end_index = solar_system.index(planet2)

    if start_index == end_index:
        return ()

    if start_index < end_index:
        planets_between = solar_system[start_index+1:end_index]
    else:
        planets_between = solar_system[end_index+1:start_index]

    return tuple([planet for planet in planets_between if planet != planet1 and planet != planet2])

